#include <iostream>
using namespace std;

class Counter {
    static int count;          // one copy shared by all objects
    int id;
public:
    Counter() { id = ++count; }
    int getId() const { return id; }
    static int total() { return count; }
};
int Counter::count = 0;        // definition outside the class

int main() {
    Counter a, b, c;
    cout << b.getId() << " " << Counter::total() << endl;
    return 0;
}

#include <iostream>
using namespace std;

class A {
public:
    A()  { cout << "A "; }
    ~A() { cout << "~A "; }
};
class B : public A {
public:
    B()  { cout << "B "; }
    ~B() { cout << "~B "; }
};

int main() {
    B obj;
    cout << "| ";
    return 0;   // obj destroyed here
}

class Animal {
    void sound() { System.out.println("Some sound"); }
}
class Dog extends Animal {
    @Override
    void sound() { System.out.println("Bark"); }
}
public class Test {
    public static void main(String[] args) {
        Animal a = new Dog();   // superclass reference, subclass object
        a.sound();              // resolved at run time
    }
}

#include <iostream>
using namespace std;

class Complex {
    int re, im;
public:
    Complex(int r = 0, int i = 0) : re(r), im(i) {}
    Complex operator+(const Complex &c) const {
        return Complex(re + c.re, im + c.im);
    }
    void show() const { cout << re << " + " << im << "i" << endl; }
};

int main() {
    Complex a(2, 3), b(4, 5);
    Complex c = a + b;      // calls a.operator+(b)
    c.show();
    return 0;
}

#include <iostream>
using namespace std;

class Shape {
public:
    void name()         { cout << "Shape" << endl; }
    virtual void draw() { cout << "Shape::draw" << endl; }
    virtual ~Shape() {}
};
class Circle : public Shape {
public:
    void name() { cout << "Circle" << endl; }
    void draw() { cout << "Circle::draw" << endl; }
};

int main() {
    Shape *p = new Circle();
    p->name();   // non-virtual: decided by pointer type
    p->draw();   // virtual: decided by object type
    delete p;
    return 0;
}

#include <iostream>
using namespace std;

template <typename T>
T maxOf(T a, T b) { return (a > b) ? a : b; }

int divide(int a, int b) {
    if (b == 0) throw "Division by zero";
    return a / b;
}

int main() {
    cout << maxOf(3, 7) << " " << maxOf(2.5, 1.5) << " "
         << maxOf('a', 'z') << endl;
    try {
        cout << divide(10, 2) << endl;
        cout << divide(1, 0) << endl;      // throws
        cout << "skipped" << endl;
    } catch (const char *msg) {
        cout << "Caught: " << msg << endl;
    }
    cout << "End" << endl;
    return 0;
}

public class ExDemo {
    static int divide(int a, int b) { return a / b; }

    public static void main(String[] args) {
        try {
            System.out.println(divide(10, 2));
            System.out.println(divide(5, 0));
            System.out.println("not printed");
        } catch (ArithmeticException e) {
            System.out.println("Caught: " + e.getMessage());
        } finally {
            System.out.println("finally runs");
        }
    }
}

public class Demo {
    public static void main(String[] args) {
        System.out.println("A" + 1 + 2);
        System.out.println(1 + 2 + "A");
        System.out.println('a' + 1);
        System.out.println(7 / 2 + " " + 7 % 3 + " " + 7.0 / 2);
        int x = 5;
        int y = x++ + ++x;      // 5 + 7
        System.out.println(x + " " + y);
    }
}

class Worker extends Thread {
    public void run() {
        System.out.println("Worker running");
    }
}
public class Main {
    public static void main(String[] args) throws InterruptedException {
        Worker t = new Worker();
        t.start();   // new thread executes run()
        t.join();    // main waits until t finishes
        System.out.println("Main done");
    }
}

